/* global window, getComputedStyle, document, innerWidth, innerHeight -- inspectTargetElement runs in the browser through the fixed MCP evaluation. */
// Read-only grounding for native computer input. Never dispatch a DOM action.
export const browserTargetTool = {
  name: "browser_inspect_target",
  description:
    "Inspect a current top-level accessibility ref from browser_snapshot or browser_find. Returns visible native-computer coordinates that currently hit that element, or why none were found, plus actual keyboard focus. Use before clicking a small, overlapping or uncertain control, or to verify focus after native Tab navigation. focused is true only when this exact element has focus, not a child control. This does not click, scroll, focus or authorize an action. Coordinates and focus can change; inspect again after changes. Frame refs are not supported.",
  inputSchema: {
    type: "object",
    properties: {
      ref: {
        type: "string",
        description: "Current top-level snapshot ref, such as e42.",
      },
    },
    required: ["ref"],
    additionalProperties: false,
  },
  annotations: { readOnlyHint: true },
};

export function inspectTargetElement(element) {
  if (window !== window.top)
    return { status: "frame-not-supported", point: null };
  const describe = (node) =>
    node
      ? {
          tag: node.tagName.toLowerCase(),
          role: node.getAttribute("role"),
          label: node.getAttribute("aria-label"),
          text: node.matches('button, a, [role="button"], [role="link"]')
            ? node.innerText?.trim()
            : undefined,
        }
      : null;
  const r = element.getBoundingClientRect();
  const bounds = { x: r.x, y: r.y, width: r.width, height: r.height };
  let active = document.activeElement;
  while (active?.shadowRoot?.activeElement)
    active = active.shadowRoot.activeElement;
  const base = {
    element: describe(element),
    bounds,
    keyboard: {
      focused: active === element,
      tabIndex: element.tabIndex,
      activeElement: describe(active),
    },
  };
  let ancestor = element;
  while (ancestor) {
    const style = getComputedStyle(ancestor);
    if (
      style.visibility !== "visible" ||
      style.display === "none" ||
      Number(style.opacity) === 0
    )
      return { ...base, status: "not-visible", point: null };
    ancestor = ancestor.parentElement ?? ancestor.getRootNode()?.host;
  }
  const disabled =
    element.matches(":disabled") ||
    element.getAttribute("aria-disabled") === "true";
  const hit = (x, y) => {
    let node = document.elementFromPoint(x, y);
    while (node?.shadowRoot) {
      const inner = node.shadowRoot.elementFromPoint(x, y);
      if (!inner || inner === node) break;
      node = inner;
    }
    let current = node;
    while (current && current !== element)
      current = current.parentElement ?? current.getRootNode()?.host;
    return { matches: current === element, node };
  };
  const center = { x: r.x + r.width / 2, y: r.y + r.height / 2 };
  const centerHit = hit(center.x, center.y);
  const ancestors = [];
  for (
    let parent = centerHit.node?.parentElement;
    parent;
    parent = parent.parentElement
  ) {
    if (parent.getAttribute("aria-label") || parent.getAttribute("role"))
      ancestors.push(describe(parent));
  }
  const centerObservation = {
    ...center,
    hitsTarget: centerHit.matches,
    receiver: describe(centerHit.node),
    ancestors,
  };
  for (const rect of element.getClientRects()) {
    const left = Math.max(rect.left, 0),
      top = Math.max(rect.top, 0);
    const right = Math.min(rect.right, innerWidth),
      bottom = Math.min(rect.bottom, innerHeight);
    if (right <= left || bottom <= top) continue;
    for (const fx of [0.5, 0.25, 0.75, 0.1, 0.9]) {
      for (const fy of [0.5, 0.25, 0.75, 0.1, 0.9]) {
        const x = left + (right - left) * fx,
          y = top + (bottom - top) * fy;
        if (hit(x, y).matches)
          return {
            ...base,
            status: disabled ? "disabled" : "available",
            point: { x, y },
            center: centerObservation,
          };
      }
    }
  }
  return {
    ...base,
    status: disabled ? "disabled" : "no-visible-point-found",
    point: null,
    center: centerObservation,
  };
}

export async function inspectBrowserTarget(mcp, ref, options) {
  if (typeof ref !== "string" || !/^(?:f\d+)?e\d+$/.test(ref))
    throw new Error(
      "Use a current snapshot ref. Nested frames are not supported.",
    );
  // Resolve in the same connection that produced the reference. The provider
  // cannot supply JavaScript; only this fixed observational function is sent.
  const result = await mcp.callToolResult(
    "browser_evaluate",
    {
      target: ref,
      element: "selected target",
      function: inspectTargetElement.toString(),
    },
    undefined,
    options,
  );
  if (result.isError) return result;
  const text = result.content
    ?.filter((block) => block.type === "text")
    .map((block) => block.text)
    .join("\n");
  if (!text?.startsWith("### Result\n"))
    throw new Error("Unexpected target inspection response");
  const value = JSON.parse(
    text.slice("### Result\n".length).split("\n### ")[0],
  );
  return {
    content: [{ type: "text", text: JSON.stringify({ ref, ...value }) }],
  };
}
